nter;margin-left:-5px;font-size:20px;position:relative}.member:first-child{margin-left:0}.member-count{font-size:10px;color:#89978e;margin-left:9px}.wealth-line,.wealth-caption{display:flex;align-items:center;justify-content:space-between}.wealth-line{border-top:1px solid #f0f2ed;padding-top:12px;color:#849188;font-size:10px}.wealth-line strong{font:700 12px Manrope;color:#2b3c33}.wealth-meter{height:5px;border-radius:5px;background:#edf1eb;margin:9px 0 11px;overflow:hidden}.wealth-meter span{display:block;height:100%;border-radius:5px;background:linear-gradient(90deg,#91cda0,#c0e8bd);width:80%;transition:width .5s}.wealth-caption{font-size:8px;letter-spacing:1px;color:#a0aaa3}.wealth-caption strong{font-size:9px;letter-spacing:0;color:#6d9d77}.needs-panel{padding-bottom:12px}.needs-list{margin-top:13px}.need-row{display:grid;grid-template-columns:23px 1fr auto;align-items:center;gap:8px;margin:10px 0}.need-emoji{font-size:14px;text-align:center}.need-name{font-size:10px;color:#65756c}.need-meter{grid-column:2/4;height:4px;background:#eff2ed;border-radius:4px;margin-top:-3px;overflow:hidden}.need-meter span{display:block;height:100%;border-radius:4px;background:#a5d6ad;transition:width .5s}.need-meter span.low{background:#f2bd8c}.need-value{font-size:8px;color:#96a198}.essentials-list{margin-top:11px}.essential-row{display:flex;align-items:center;gap:9px;padding:8px 0;border-bottom:1px solid #f1f3ef}.essential-row:last-child{border-bottom:0}.essential-icon{width:27px;height:27px;border-radius:8px;display:grid;place-items:center;font-size:13px;background:#f3f5ef}.essential-row span:nth-child(2){font-size:10px;color:#75847b;flex:1}.essential-row strong{font-size:9px;text-align:right;color:#35473d;max-width:95px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.text-link{padding:9px 0 0;border:0;background:none;color:#669676;font:600 9px 'DM Sans';cursor:pointer}.text-link span{margin-left:5px}.daily-note{border-radius:12px;background:#f3f2e9;padding:12px;disp