y:block;font:700 12px Manrope;margin:6px 0 3px}.city-option small{font-size:9px;color:#87938b}.trip-summary{background:#eff5ed;border-radius:11px;padding:14px;margin-top:14px;display:flex;justify-content:space-between;align-items:center}.trip-summary small{display:block;font-size:8px;color:#829087;letter-spacing:1px}.trip-summary strong{font:700 13px Manrope}.class-options{display:flex;gap:7px;margin-top:12px}.class-option{flex:1;background:white;border:1px solid #e8ede6;border-radius:9px;padding:10px 6px;cursor:pointer;color:#62736a}.class-option strong{display:block;font-size:10px}.class-option small{font-size:8px}.class-option.selected{background:#20382e;color:#e9fff0;border-color:#20382e}.modal-primary{width:100%;border:0;border-radius:9px;background:#294438;color:white;padding:13px;margin-top:13px;font:700 11px 'DM Sans';cursor:pointer}.modal-primary:disabled{opacity:.45;cursor:not-allowed}.trip-choice{display:flex;justify-content:space-between;gap:10px;align-items:center;padding:12px 0;border-bottom:1px solid #edf0ea}.trip-choice:last-child{border-bottom:0}.trip-choice-label{display:flex;gap:10px;align-items:center}.trip-choice-emoji{font-size:20px}.trip-choice strong{display:block;font-size:11px}.trip-choice small{font-size:9px;color:#85928b}.trip-choice button{border:1px solid #e5ebe4;background:#f8faf6;border-radius:8px;padding:8px 10px;color:#61756a;font-size:9px;cursor:pointer}.trip-choice button:hover{background:#e9f4e9}.family-modal-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:16px}.family-choice{border:1px solid #e7ece5;border-radius:11px;padding:12px 10px;background:white;cursor:pointer;text-align:left}.family-choice.active{background:#eff7ef;border-color:#a9d2b0}.family-choice .family-art{font-size:25px}.family-choice strong{display:block;font-size:10px;margin-top:7px}.family-choice small{font-size:8px;color:#8a968e}.toast{position:fixed;z-index:20;bottom:26px;left:50%;transform:translate(-50%,20px);padding:11px 16px;backg