const families = [
  {id:'whitmore',name:'The Whitmores',short:'Whitmores',tier:'Ultra wealthy',emoji:'👨‍👩‍👧',people:[['👨🏻','#d9b497'],['👩🏼',' #ddc2b2'],['👧🏼','#d5a77f']],funds:12850000,net:48500000,monthly:48200,wealth:96,home:'The Sunrise Estate',place:'Beverly Hills',homeType:'Modern glass mansion',job:'Creative director',business:'The family office',cars:'3 luxury cars',aircraft:'Private jet',insurance:'Full coverage',clothes:'Designer wardrobe',homeIcon:'⌂',vehicles:'🚘',air:'✈',needs:[82,71,91,67],jobPay:1450,businessPay:3800,tip:'The best things in life are even better when shared.'},
