  {id:'rivera',name:'The Riveras',short:'Riveras',tier:'Average family',emoji:'👩‍👦',people:[['👩🏽','#bb8768'],['👦🏽','#c79871']],funds:8450,net:32400,monthly:1850,wealth:24,home:'Maple Street Home',place:'Silver Lake',homeType:'Cozy city home',job:'Nurse & weekend baker',business:'Rivera Sunday Bakes',cars:'One reliable car',aircraft:'Commercial flights',insurance:'Everyday essentials',clothes:'Comfort-first style',homeIcon:'⌂',vehicles:'🚗',air:'✈',needs:[62,75,71,58],jobPay:185,businessPay:95,tip:'Small moments make a very good life.'}
];
