];
const state={active:0,tripCity:null,travelClass:'Economy',away:false,day:1,sound:true};
const $=s=>document.querySelector(s); const money=n=>'$'+Math.round(n).toLocaleString('en-US');
function current(){return families[state.active]}
function render(){const f=current();$('#top-money').textContent=money(f.funds);$('#household-name').textContent=f.name;$('#net-worth').textContent=money(f.net);$('#wealth-label').textContent=f.tier+' household';$('#wealth-meter-fill').style.width=f.wealth+'%';$('#monthly-change').textContent='↗ '+money(f.monthly);$('#work-label').textContent=f.job;$('#business-label').textContent=f.business;$('#care-label').textContent=state.away?'Recharge on vacation':'Feel like yourself';
 $('#family-switcher').innerHTML=families.map((x,i)=>`<button class="family-chip ${i===state.active?'active':''}" data-family="${i}"><span class="chip-emoji">${x.emoji}</span>${x.short}</button>`).join('');
 $('#household-members').innerHTML=f.people.map(p=>`<span class="member" style="background:${p[1].trim()}">${p[0]}</span>`).join('')+`<span class="member-count">${f.people.length} ${f.people.length===1?'member':'members'}</span>`;
 const needNames=[['☼','Energy'],['♡','Happiness'],['✳','Social'],['◉','Comfort']];$('#needs-list').innerHTML=f.needs.map((n,i)=>`<div class="need-row"><span class="need-emoji">${needNames[i][0]}</span><span class="need-name">${needNames[i][1]}</span><span class="need-value">${n}%</span><div class="need-meter"><span class="${n<40?'low':''}" style="width:${n}%"></span></div></div>`).join('');
 const stuff=[['⌂','Home',f.homeType],['✧','Style',f.clothes],['▣','On the road',f.cars],['✈','In the air',f.aircraft],['♡','Peace of mind',f.insurance]];$('#essentials-list').innerHTML=stuff.map(x=>`<div class="essential-row"><span class="essential-icon">${x[0]}</span><span>${x[1]}</span><strong>${x[2]}</strong></div>`).join('');
 $('#daily-tip').textContent=state.away?`Take the long way back. You're in ${state.tripCity.name}.`:f.tip;
 $('#scene-location').textContent=state.away?state.tripCity.place+' · '+state.tripCity.country.toUpperCase():`HOME · ${f.place.toUpperCase()}`;$('#scene-caption').textContent=state.away?state.tripCity.name.toUpperCase()+' ESCAPE':f.home.toUpperCase();$('#scene-subcaption').textContent=state.away?'A new city, a fresh perspective':`A lovely ${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][(state.day+5)%7]} at home`;
 $('#scene-art').innerHTML=sceneSVG(f,state.away?state.tripCity:null);document.querySelectorAll('.rail-btn[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='home'));
}
