 <!-- home side + facade --> <path d="M315 218 L493 155 L673 218 L673 347 L493 412 L315 344Z" fill="${wall}"/><path d="M493 155 L673 218 L673 347 L493 412Z" fill="${home?'#d9dfd0':'#d0bea5'}"/><path d="M282 219 L493 137 L706 216 L673 232 L493 171 L315 237Z" fill="${roof}"/><path d="M493 137 L706 216 L673 232 L493 171Z" fill="${f.id==='whitmore'?'#718779':'#66554b'}"/>
