 ${!isAway?`<g transform="translate(${f.id==='whitmore'?660:675} 376)"><path d="M0 19L10 6H49L61 18V32H2Z" fill="${f.id==='whitmore'?'#344b45':f.id==='park'?'#b67f55':'#6d8675'}"/><path d="M14 8H31V18H7Z" fill="#b6d4ca"/><path d="M35 8H46L55 18H35Z" fill="#b6d4ca"/><circle cx="14" cy="32" r="7" fill="#39433e"/><circle cx="49" cy="32" r="7" fill="#39433e"/></g>`:''}
