function openModal(html){$('#modal-content').innerHTML=html;$('#modal-backdrop').hidden=false;document.body.style.overflow='hidden'}function closeModal(){$('#modal-backdrop').hidden=true;document.body.style.overflow=''}
let toastTimer;function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2450)}
function travelModal(){state.tripCity=state.tripCity||destinations[1];const f=current();let selected=state.tripCity;let cabin=state.travelClass;const calc=()=>Math.round(selected.cost*f.people.length*({Economy:1,'Business class':2.35,'First class':4.2}[cabin]));const html=()=>`<div class="modal-kicker">✈ &nbsp;GO A LITTLE FURTHER</div><h2>Where to next?</h2><p class="modal-intro">Pick a city and your way to get there. We’ll take care of the rest.</p><div class="city-grid">${destinations.map((d,i)=>`<button class="city-option ${d.name===selected.name?'selected':''}" data-city="${i}"><span class="city-emoji">${d.emoji}</span><strong>${d.name}</strong><small>${d.country} · from ${money(d.cost)} / person</small></button>`).join('')}</div><div class="class-options">${[['Economy','Easy on the budget'],['Business class','A little extra room'],['First class','Make it special']].map(([n,sub])=>`<button class="class-option ${n===cabin?'selected':''}" data-cabin="${n}"><strong>${n==='Economy'?'◉':n==='Business class'?'✧':'✦'} &nbsp;${n}</strong><small>${sub}</small></button>`).join('')}</div><div class="trip-summary"><div><small>ROUND-TRIP TOTAL · ${f.people.length} ${f.people.length===1?'TRAVELER':'TRAVELERS'}</small><strong>${selected.name} · ${cabin}</strong></div><strong>${money(calc())}</strong></div><button class="modal-primary" id="book-trip" ${calc()>f.funds?'disabled':''}>${calc()>f.funds?'Not quite enough funds':'Book this getaway · '+money(calc())}</button>`;openModal(html());$('#modal-content').addEventListener('click',e=>{const c=e.target.closest('[data-city]'),cl=e.target.closest('[data-cabin]');if(c){selected=destinations[Number(c.dataset.city)];refresh()}if(cl){cabin=cl.dataset.cabin;refresh()}if(e.target.closest('#book-trip')){const price=calc();if(price>f.funds)return;f.funds-=price;f.net-=price;state.tripCity=selected;state.travelClass=cabin;state.away=true;closeModal();render();toast(`Booked! ${selected.name} is calling. Safe travels ✈`)}},{once:false});function refresh(){const old=$('#modal-content');old.innerHTML=html()}}
function familyModal(){const f=current();openModal(`<div class="modal-kicker">YOUR PEOPLE, YOUR STORY</div><h2>Choose a household</h2><p class="modal-intro">Three different beginnings. Each life comes with its own home, work, transport and possibilities.</p><div class="family-modal-grid">${families.map((x,i)=>`<button class="family-choice ${i===state.active?'active':''}" data-family="${i}"><span class="family-art">${x.emoji}</span><strong>${x.name}</strong><small>${x.tier}<br>${money(x.funds)} funds</small></button>`).join('')}</div><div class="trip-summary"><div><small>SELECTED HOUSEHOLD</small><strong>${f.home} · ${f.place}</strong></div><strong>${money(f.funds)}</strong></div>`);$('#modal-content').onclick=e=>{const b=e.target.closest('[data-family]');if(b){state.active=Number(b.dataset.family);state.away=false;render();familyModal()}}}
function profileModal(){const f=current();openModal(`<div class="modal-kicker">THE ${f.tier.toUpperCase()} LIFE</div><h2>${f.name}</h2><p class="modal-intro">Your life is already in motion. Here's the lifestyle that comes with this household.</p><div class="essentials-list">${[['Home',f.homeType+' · '+f.place],['Clothes',f.clothes],['Work',f.job],['Business',f.business],['Cars',f.cars],['Aircraft',f.aircraft],['Insurance',f.insurance]].map(([a,b])=>`<div class="essential-row"><span class="essential-icon">✧</span><span>${a}</span><strong>${b}</strong></div>`).join('')}</div><div class="trip-summary"><div><small>AVAILABLE HOUSEHOLD FUNDS</small><strong>Net worth ${money(f.net)}</strong></div><strong>${money(f.funds)}</strong></div>`)}
function action(type){const f=current();if(type==='work'){const gain=f.jobPay;f.funds+=gain;f.net+=gain;f.needs=[Math.max(20,f.needs[0]-13),Math.max(20,f.needs[1]-3),Math.max(20,f.needs[2]-5),f.needs[3]];render();toast(`Good work! ${money(gain)} earned as ${f.job}.`)}else if(type==='business'){openModal(`<div class="modal-kicker">A LITTLE AMBITION</div><h2>${f.business}</h2><p class="modal-intro">Put in a focused day and see what your family venture can do.</p><div class="trip-summary"><div><small>ESTIMATED TODAY'S RETURN</small><strong>${f.business}</strong></div><strong>+${money(f.businessPay)}</strong></div><p class="modal-intro" style="margin:14px 0 0">Business income varies with the life you've built. The family has ${f.aircraft.toLowerCase()} and ${f.insurance.toLowerCase()}.</p><button class="modal-primary" id="run-business">Put in a day · earn ${money(f.businessPay)}</button>`);$('#modal-content').onclick=e=>{if(e.target.closest('#run-business')){f.funds+=f.businessPay;f.net+=f.businessPay;f.needs[0]=Math.max(20,f.needs[0]-9);render();closeModal();toast(`Your business brought in ${money(f.businessPay)} today.`)}}}else if(type==='care'){openModal(`<div class="modal-kicker">MAKE SPACE FOR YOURSELF</div><h2>A slower, sweeter day.</h2><p class="modal-intro">Choose something that feels good. Taking care of your people is part of the plan.</p><div class="trip-choice"><div class="trip-choice-label"><span class="trip-choice-emoji">🧘</span><div><strong>A quiet reset</strong><small>Rest, recharge and find your balance</small></div></div><button data-care="reset">Take a breather</button></div><div class="trip-choice"><div class="trip-choice-label"><span class="trip-choice-emoji">🥐</span><div><strong>A treat together</strong><small>Spend $35 · share a little joy</small></div></div><button data-care="treat">Make it lovely</button></div><div class="trip-choice"><div class="trip-choice-label"><span class="trip-choice-emoji">🌳</span><div><strong>Get outside</strong><small>A free family walk and fresh air</small></div></div><button data-care="outside">Head out</button></div>`);$('#modal-content').onclick=e=>{const b=e.target.closest('[data-care]');if(!b)return;const choice=b.dataset.care;if(choice==='treat'&&f.funds<35){toast('Not enough funds for this treat just yet.');return}if(choice==='treat'){f.funds-=35;f.net-=35}f.needs=choice==='reset'?f.needs.map((n,i)=>Math.min(100,n+(i===0?36:i===1?10:4))):choice==='outside'?f.needs.map((n,i)=>Math.min(100,n+(i===2?31:i===1?14:7))):f.needs.map((n,i)=>Math.min(100,n+(i===1?36:i===2?15:6)));render();closeModal();toast(choice==='reset'?'A little rest goes a long way.':choice==='outside'?'Fresh air, full hearts.':'A lovely little moment together.') }} }
function dayEnd(){const f=current();state.day++;f.funds=Math.max(0,f.funds-25*f.people.length);f.needs=f.needs.map(n=>Math.max(15,n-8));if(state.away){state.away=false;toast('Back home, with stories to tell. A new day begins.')}else toast(`Day ${state.day} begins. A little household upkeep has been paid.`);render()}
document.addEventListener('click',e=>{const fam=e.target.closest('.family-chip,[data-family]');if(fam&&fam.dataset.family!==undefined){state.active=Number(fam.dataset.family);state.away=false;render();if(fam.classList.contains('family-choice'))familyModal();return}const view=e.target.closest('[data-view]');if(view){if(view.dataset.view==='travel'||view.dataset.view==='world')travelModal();else if(view.dataset.view==='family')familyModal();else render();return}const act=e.target.closest('[data-action]');if(act){action(act.dataset.action);return}if(e.target.closest('#explore-btn')){profileModal();return}if(e.target.closest('#advance-day')){dayEnd();return}if(e.target.closest('#modal-close')||e.target.id==='modal-backdrop'){closeModal();return}if(e.target.closest('#sound-toggle')){state.sound=!state.sound;toast(state.sound?'Sound is on.':'Sound is off.');return}if(e.target.closest('#notifications')){toast('A calm day, full of possibilities.');return}if(e.target.closest('#scene-more')){profileModal();return}if(e.target.closest('.text-link')){profileModal()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});render();

